package com.familyfinance.loan;
import static org.assertj.core.api.Assertions.assertThat;
import com.familyfinance.category.*; import com.familyfinance.household.*; import com.familyfinance.ledger.*; import java.math.BigDecimal; import java.time.LocalDate; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.ActiveProfiles; import jakarta.persistence.EntityManager; import org.springframework.transaction.annotation.Transactional;
@ActiveProfiles("test") @SpringBootTest(properties="app.seed.enabled=true") class LoanSchedulePersistenceTest {
 @Autowired LoanRepository loans; @Autowired FinancialAccountRepository accounts; @Autowired CategoryRepository categories; @Autowired HouseholdRepository households; @Autowired AppUserRepository users; @Autowired EntityManager em;
 @Test @Transactional void persistedScheduleReloadsWithExactCalculatorCentsAndDates(){Household h=households.findById(1L).orElseThrow();FinancialAccount a=accounts.findFirstByHouseholdIdAndArchivedAtIsNullOrderById(1L).orElseThrow();Category c=categories.findByHouseholdIdOrderById(1L).stream().filter(x->x.getKind()==TransactionKind.EXPENSE).findFirst().orElseThrow();AppUser u=users.findByUsername("demo").orElseThrow();Loan loan=new Loan(h,"持久化房贷",LoanType.MORTGAGE,null,null,null,a,c,10_000L,new BigDecimal("0.120000"),3,RepaymentMethod.EQUAL_PAYMENT,LocalDate.of(2024,1,31),u);loan.replaceSchedule(new AmortizationCalculator().calculate(10_000L,new BigDecimal("0.120000"),3,LocalDate.of(2024,1,31),RepaymentMethod.EQUAL_PAYMENT));long id=loans.saveAndFlush(loan).getId();em.clear();Loan reloaded=loans.findById(id).orElseThrow();assertThat(reloaded.getInstallments()).extracting(LoanInstallment::getPrincipalCents).containsExactly(3_300L,3_333L,3_367L);assertThat(reloaded.getInstallments()).extracting(LoanInstallment::getDueOn).containsExactly(LocalDate.of(2024,2,29),LocalDate.of(2024,3,31),LocalDate.of(2024,4,30));}
}
